result = env['export.report'].generate_programs_report()
if result.get('success'):
    action = {
        'type': 'ir.actions.client',
        'tag': 'reload',
        'params': {'menu_id': env.ref('school_export_reports.menu_export_reports').id}
    }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'type': 'danger',
            'title': 'Report Generation Failed',
            'message': 'Unable to generate programs report. Please check CSV file.',
            'sticky': False,
        }
    }

